INSERT INTO `commentaires` (`auteur_nom`, `contenu`, `note`, `pays`, `service_type`, `service_id`) VALUES
('Mohammed A.', 'تجربة رائعة جداً! المرشد كان ممتازاً والفندق في قمة الروعة. أنصح الجميع بالتعامل مع هذه الوكالة لزيارة مراكش.', 5, NULL, NULL, NULL),
('Sarah L.', 'Très bien organisé. Les restaurants recommandés étaient délicieux. Tout était parfait du début à la fin de notre séjour.', 5, NULL, NULL, NULL),
('visitor1', 'perfect website', 5, NULL, NULL, NULL),
('John D.', 'Amazing experience! Morocco is a beautiful country and the tour was perfectly planned. Highly recommended for everyone.', 5, NULL, NULL, NULL),
('Maria G.', 'Una experiencia inolvidable. El servicio fue excelente y la gente muy amable. Volveremos pronto sin duda.', 4, NULL, NULL, NULL),
('Anonyme', 'Magnifique experience, jadore !', 5, NULL, NULL, NULL),
('Ahmed T.', 'Service exceptionnel! J\'ai pu réserver un hôtel et un restaurant en quelques clics. Très fluide et sécurisé.', 5, NULL, NULL, NULL),
('Anonyme', 'Excellent service, je recommande !', 5, NULL, NULL, NULL),
('Anonyme', 'Test comment from automated verification. Morocco is amazing!', 5, NULL, NULL, NULL),
('Anonyme', 'C\'est un site magnifique, j\'adore l\'exp', 4, NULL, NULL, NULL);
